def _parse_plan(raw: object, index: int) -> _Plan:
    what = f"plans[{index}]"
    obj = _require_fields(raw, _PLAN_FIELDS, what)
    target = _parse_entry(obj["target"], allow_wildcard=False)
    stages = obj["stages"]
