        action = {
            "remediation_id": remediation.id,
            "title": remediation.title,
            "guidance": remediation.guidance,
            "status": status,
            "reason": reason,
            "matched_template_ids": matched,
        }
        entered[remediation.id] = action

    actions = list(entered.values())
